user_code = code
tree = ast.parse(user_code)

found_import = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 're' for name in node.names):
        found_import = True
    if isinstance(node, ast.ImportFrom) and node.module == 're':
        found_import = True

if not found_import:
    raise AssertionError('Task 1: Missing import re module')

